// === REPORT CARD MODULE ===
// Builds a printable/downloadable student report card (subjects, scores,
// grades, totals, remark) styled after the school's report card design,
// with the school logo. Used from both the Teacher dashboard (their own
// students) and the Admin dashboard (any student, across all teachers).

const REPORT_LOGO_BASE64 = "";

function scoreToGrade(percentage) {
    if (percentage >= 92) return 'A';
    if (percentage >= 86) return 'B+';
    if (percentage >= 81) return 'B';
    if (percentage >= 76) return 'C';
    if (percentage >= 60) return 'D';
    return 'F';
}

// --- Period helper: periods run the 15th of one month to the 14th of the next ---
function getCurrentPeriod(date = new Date()) {
    const day = date.getDate();
    let start, end;
    if (day >= 15) {
        start = new Date(date.getFullYear(), date.getMonth(), 15);
        end = new Date(date.getFullYear(), date.getMonth() + 1, 14);
    } else {
        start = new Date(date.getFullYear(), date.getMonth() - 1, 15);
        end = new Date(date.getFullYear(), date.getMonth(), 14);
    }
    const toStr = d => d.toISOString().slice(0, 10);
    return { start: toStr(start), end: toStr(end) };
}

function formatPeriodLabel(startStr, endStr) {
    const opts = { month: 'short', day: 'numeric', year: 'numeric' };
    const s = new Date(startStr + 'T00:00:00').toLocaleDateString(undefined, opts);
    const e = new Date(endStr + 'T00:00:00').toLocaleDateString(undefined, opts);
    return `${s} - ${e}`;
}

// Returns [{ subject, score, total, percentage, grade, teacherId, teacherName, assessmentType }],
// one row per subject, using that subject's BEST (highest-percentage) submitted attempt,
// across ALL teachers this student has.
async function getStudentSubjectSummary(studentId) {
    const { data: attempts, error: attemptsErr } = await window.mySupabase
        .from('attempts')
        .select('assessment_id, score, total, percentage')
        .eq('student_id', studentId)
        .eq('status', 'submitted');
    if (attemptsErr || !attempts || attempts.length === 0) return [];

    const assessmentIds = [...new Set(attempts.map(a => a.assessment_id))];
    const { data: assessments, error: assessErr } = await window.mySupabase
        .from('assessment')
        .select('id, subject, teacher_id, assessment_type')
        .in('id', assessmentIds);
    if (assessErr || !assessments) return [];

    const { data: teachers } = await window.mySupabase.from('teachers').select('id, name, username');
    const teacherNameById = {};
    (teachers || []).forEach(t => { teacherNameById[t.id] = t.name || t.username; });

    const infoByAssessment = {};
    assessments.forEach(a => {
        infoByAssessment[a.id] = {
            subject: a.subject || 'General',
            teacherId: a.teacher_id,
            teacherName: teacherNameById[a.teacher_id] || 'Unknown Teacher',
            assessmentType: a.assessment_type || 'monthly'
        };
    });

    const bestBySubject = {};
    attempts.forEach(a => {
        const info = infoByAssessment[a.assessment_id];
        if (!info) return;
        const key = info.subject;
        if (!bestBySubject[key] || a.percentage > bestBySubject[key].attempt.percentage) {
            bestBySubject[key] = { attempt: a, info };
        }
    });

    return Object.keys(bestBySubject).sort().map(subject => {
        const { attempt, info } = bestBySubject[subject];
        return {
            subject, score: attempt.score, total: attempt.total, percentage: attempt.percentage,
            grade: scoreToGrade(attempt.percentage),
            teacherId: info.teacherId, teacherName: info.teacherName, assessmentType: info.assessmentType
        };
    });
}

// Renders the subject checklist, split into Pop Quiz / Monthly Assessment groups.
async function loadReportSubjectChecklist(studentId, targetListId) {
    const container = document.getElementById(targetListId);
    container.innerHTML = "<p style='color:#888;'>Loading subjects...</p>";
    if (!studentId) { container.innerHTML = "<p style='color:#888;'>Select a student first.</p>"; return; }

    const rows = await getStudentSubjectSummary(studentId);
    if (rows.length === 0) {
        container.innerHTML = "<p style='color:#888;'>This student has no completed tests yet.</p>";
        container.dataset.rows = '[]';
        return;
    }
    container.dataset.rows = JSON.stringify(rows);

    const renderGroup = (label, type) => {
        const items = rows.map((r, i) => ({ r, i })).filter(x => x.r.assessmentType === type);
        if (items.length === 0) return '';
        return `<div style="margin-bottom:10px;"><strong style="font-size:13px;color:#7c5cff;">${label}</strong>` +
            items.map(({ r, i }) => `
                <label style="display:flex;align-items:center;gap:8px;margin:6px 0 0;font-weight:normal;">
                    <input type="checkbox" class="report-subject-check" data-index="${i}" data-type="${r.assessmentType}" data-teacher="${r.teacherId}" style="width:auto;" checked>
                    ${r.subject} (${r.teacherName}) — ${r.score}/${r.total} (${r.percentage}%, Grade ${r.grade})
                </label>`).join('') + `</div>`;
    };

    container.innerHTML = renderGroup('POP QUIZ RESULTS', 'pop_quiz') + renderGroup('MONTHLY ASSESSMENT RESULTS', 'monthly');
}

function buildReportHtml({ studentName, bannerLabel, periodLabel, rows, remark }) {
    const totalObtainable = rows.reduce((sum, r) => sum + r.total, 0);
    const totalObtained = rows.reduce((sum, r) => sum + r.score, 0);
    const overallPercentage = totalObtainable > 0 ? Math.round((totalObtained / totalObtainable) * 100) : 0;
    const overallGrade = scoreToGrade(overallPercentage);

    const subjectRowsHtml = rows.map(r => `
        <tr>
            <td>${r.subject}${r.teacherName ? ` <span style="color:#999;font-size:12px;">(${r.teacherName})</span>` : ''}</td>
            <td style="text-align:center;">${r.total}</td>
            <td style="text-align:center;">${r.score}</td>
            <td style="text-align:center;font-weight:bold;">${r.grade}</td>
        </tr>`).join('');

    return `<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><title>${studentName} - ${bannerLabel}</title>
<style>
    * { box-sizing: border-box; font-family: 'Segoe UI', Tahoma, Arial, sans-serif; margin:0; padding:0; }
    body { background:#eef1f8; padding:30px; }
    .sheet { max-width:800px; margin:0 auto; background:#fff; border-radius:10px; overflow:hidden; box-shadow:0 6px 20px rgba(0,0,0,0.12); }
    .banner { display:flex; align-items:center; }
    .logo-box { background:#eef1f8; padding:18px; }
    .logo-box img { height:90px; }
    .title-box { background:#1e2f66; color:#fff; flex:1; padding:20px 25px; }
    .title-box h1 { color:#f0a233; font-size:28px; letter-spacing:1px; }
    .title-box p { font-size:16px; margin-top:4px; }
    .student-row { padding:20px 25px 5px; font-size:16px; color:#333; display:flex; justify-content:space-between; flex-wrap:wrap; gap:6px; }
    .section-header { background:#f0a233; color:#fff; padding:8px 25px; font-weight:bold; letter-spacing:1px; margin-top:15px; }
    table { width:100%; border-collapse:collapse; margin:0 0 10px; }
    th, td { padding:10px 25px; border-bottom:1px solid #eee; font-size:14px; }
    th { text-align:left; color:#1e2f66; background:#f7f9fd; }
    .totals-row td { font-weight:bold; background:#f7f9fd; }
    .bottom-grid { display:flex; gap:20px; padding:0 25px 25px; margin-top:10px; flex-wrap:wrap; }
    .bottom-box { flex:1; min-width:220px; }
    .bottom-box .section-header { margin:0 0 10px; border-radius:6px; }
    .remark-box { min-height:80px; border:1px solid #eee; border-radius:6px; padding:12px; font-size:14px; color:#333; }
    .grade-scale { font-size:13px; color:#333; line-height:1.9; }
    .footer { text-align:center; font-size:11px; color:#999; padding:15px; }
    .print-bar { max-width:800px; margin:0 auto 12px; text-align:right; }
    .print-bar button { background:#7c5cff; color:#fff; border:none; padding:10px 18px; border-radius:10px; font-weight:bold; cursor:pointer; font-size:14px; }
    @media print { body { background:#fff; padding:0; } .sheet { box-shadow:none; } .no-print { display:none !important; } }
</style></head>
<body>
<div class="print-bar no-print"><button onclick="window.print()">🖨️ Print / Save as PDF</button></div>
<div class="sheet">
    <div class="banner">
        <div class="logo-box"><img src="data:image/png;base64,${REPORT_LOGO_BASE64}" alt="Logo"></div>
        <div class="title-box"><h1>MATH CLASS WITH MR. GOLD</h1><p>${bannerLabel}</p></div>
    </div>
    <div class="student-row">
        <div><strong>Student:</strong> ${studentName}</div>
        <div><strong>${periodLabel ? 'Period:' : 'Date:'}</strong> ${periodLabel || new Date().toLocaleDateString()}</div>
    </div>
    <div class="section-header">ACADEMICS</div>
    <table>
        <thead><tr><th>Subject</th><th style="text-align:center;">Score Obtainable</th><th style="text-align:center;">Score Obtained</th><th style="text-align:center;">Grade</th></tr></thead>
        <tbody>
            ${subjectRowsHtml}
            <tr class="totals-row">
                <td>Total</td>
                <td style="text-align:center;">${totalObtainable}</td>
                <td style="text-align:center;">${totalObtained}</td>
                <td style="text-align:center;">${overallGrade}</td>
            </tr>
        </tbody>
    </table>
    <div class="student-row" style="padding-top:0;">
        <div><strong>Overall Percentage:</strong> ${overallPercentage}%</div>
    </div>
    <div class="bottom-grid">
        <div class="bottom-box">
            <div class="section-header">REMARKS</div>
            <div class="remark-box">${remark ? remark.replace(/</g, '&lt;') : '&nbsp;'}</div>
        </div>
        <div class="bottom-box">
            <div class="section-header">GRADING SYSTEM</div>
            <div class="grade-scale">
                A &nbsp;- 92-100<br>
                B+ - 86-91<br>
                B &nbsp;- 81-85<br>
                C &nbsp;- 76-80<br>
                D &nbsp;- 60-75<br>
                F &nbsp;- 59 below
            </div>
        </div>
    </div>
    <div class="footer">Generated by Math Class with Mr. Gold</div>
</div>
</body></html>`;
}

function getCheckedReportRows(listId, filterFn) {
    const container = document.getElementById(listId);
    const rows = JSON.parse(container.dataset.rows || '[]');
    return Array.from(container.querySelectorAll('.report-subject-check:checked'))
        .map(cb => ({ cb, row: rows[parseInt(cb.dataset.index, 10)] }))
        .filter(x => !filterFn || filterFn(x.cb, x.row))
        .map(x => x.row);
}

// --- Ad-hoc download (not persisted), used by both Teacher and Admin tabs ---
function generateReportCard(studentName, listId, remarkInputId) {
    const checked = getCheckedReportRows(listId, null);
    if (checked.length === 0) {
        alert("Select at least one subject to include in the report.");
        return;
    }
    const remark = document.getElementById(remarkInputId).value.trim();
    const html = buildReportHtml({ studentName, bannerLabel: 'Report Card', periodLabel: null, rows: checked, remark });
    downloadHtml(html, `${studentName.replace(/\s+/g, '_')}_Report_Card.html`);
}

function downloadHtml(html, filename) {
    const blob = new Blob([html], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
}

function openHtmlInNewTab(html) {
    const w = window.open('', '_blank');
    if (!w) { alert("Please allow pop-ups to view the report card."); return; }
    w.document.open();
    w.document.write(html);
    w.document.close();
}

// --- Retention: keep only the most recent 6 report cards per grouping ---
async function cleanupOldReports(studentId, teacherId, reportType) {
    let query = window.mySupabase.from('report_cards').select('id, created_at')
        .eq('student_id', studentId).eq('report_type', reportType)
        .order('created_at', { ascending: false });
    query = teacherId ? query.eq('teacher_id', teacherId) : query.is('teacher_id', null);
    const { data } = await query;
    if (data && data.length > 6) {
        const idsToDelete = data.slice(6).map(r => r.id);
        await window.mySupabase.from('report_cards').delete().in('id', idsToDelete);
    }
}

// --- Teacher: send to student portal ---
async function refreshTeacherReportSubjects() {
    const studentId = document.getElementById('assign-student').value;
    await loadReportSubjectChecklist(studentId, 'teacher-report-subjects');
}

function generateTeacherReportCard() {
    const studentName = document.getElementById('assign-student').selectedOptions[0]?.innerText || 'Student';
    generateReportCard(studentName, 'teacher-report-subjects', 'teacher-report-remark');
}

async function sendPopQuizToPortal() {
    const msg = document.getElementById('teacher-msg');
    const studentId = document.getElementById('assign-student').value;
    const myId = window.APP.currentUserId;
    const checked = getCheckedReportRows('teacher-report-subjects', (cb) => cb.dataset.type === 'pop_quiz' && String(cb.dataset.teacher) === String(myId));

    if (checked.length === 0) {
        msg.innerText = "No pop quiz subjects selected that belong to you.";
        msg.style.color = "#d9534f";
        return;
    }

    const remark = document.getElementById('teacher-report-remark').value.trim();
    const totalObtainable = checked.reduce((s, r) => s + r.total, 0);
    const totalObtained = checked.reduce((s, r) => s + r.score, 0);
    const overallPercentage = totalObtainable > 0 ? Math.round((totalObtained / totalObtainable) * 100) : 0;
    const period = getCurrentPeriod();

    try {
        const { error } = await window.mySupabase.from('report_cards').insert([{
            student_id: studentId, teacher_id: myId, report_type: 'pop_quiz',
            period_start: period.start, period_end: period.end,
            subjects: checked, total_obtainable: totalObtainable, total_obtained: totalObtained,
            overall_percentage: overallPercentage, overall_grade: scoreToGrade(overallPercentage), remark
        }]);
        if (error) { msg.innerText = `Failed to send: ${error.message}`; msg.style.color = "#d9534f"; return; }

        await cleanupOldReports(studentId, myId, 'pop_quiz');
        msg.innerText = "Pop quiz report card sent to the student's portal!";
        msg.style.color = "#28a745";
    } catch (err) {
        msg.innerText = "Unable to connect to database.";
        msg.style.color = "#d9534f";
    }
}

async function sendMonthlyToPortal() {
    const msg = document.getElementById('teacher-msg');
    const studentId = document.getElementById('assign-student').value;
    const checked = getCheckedReportRows('teacher-report-subjects', (cb) => cb.dataset.type === 'monthly');

    if (checked.length === 0) {
        msg.innerText = "No monthly assessment subjects selected.";
        msg.style.color = "#d9534f";
        return;
    }

    const remark = document.getElementById('teacher-report-remark').value.trim();
    const period = getCurrentPeriod();

    try {
        const { data: existing } = await window.mySupabase
            .from('report_cards').select('*')
            .eq('student_id', studentId).eq('report_type', 'monthly')
            .is('teacher_id', null).eq('period_start', period.start)
            .maybeSingle();

        let mergedSubjects = checked;
        if (existing && existing.subjects) {
            const bySubject = {};
            existing.subjects.forEach(s => { bySubject[s.subject] = s; });
            checked.forEach(s => { bySubject[s.subject] = s; }); // new send overwrites same subject
            mergedSubjects = Object.values(bySubject);
        }

        const totalObtainable = mergedSubjects.reduce((s, r) => s + r.total, 0);
        const totalObtained = mergedSubjects.reduce((s, r) => s + r.score, 0);
        const overallPercentage = totalObtainable > 0 ? Math.round((totalObtained / totalObtainable) * 100) : 0;

        if (existing) {
            const { error } = await window.mySupabase.from('report_cards').update({
                subjects: mergedSubjects, total_obtainable: totalObtainable, total_obtained: totalObtained,
                overall_percentage: overallPercentage, overall_grade: scoreToGrade(overallPercentage), remark
            }).eq('id', existing.id);
            if (error) { msg.innerText = `Failed to update combined report: ${error.message}`; msg.style.color = "#d9534f"; return; }
        } else {
            const { error } = await window.mySupabase.from('report_cards').insert([{
                student_id: studentId, teacher_id: null, report_type: 'monthly',
                period_start: period.start, period_end: period.end,
                subjects: mergedSubjects, total_obtainable: totalObtainable, total_obtained: totalObtained,
                overall_percentage: overallPercentage, overall_grade: scoreToGrade(overallPercentage), remark
            }]);
            if (error) { msg.innerText = `Failed to send: ${error.message}`; msg.style.color = "#d9534f"; return; }
        }

        await cleanupOldReports(studentId, null, 'monthly');
        msg.innerText = "Monthly result merged into the student's combined report card!";
        msg.style.color = "#28a745";
    } catch (err) {
        msg.innerText = "Unable to connect to database.";
        msg.style.color = "#d9534f";
    }
}

// --- Admin: same ad-hoc download tool, across all students/teachers ---
async function populateAdminStudentDropdown() {
    const drop = document.getElementById('admin-report-student');
    drop.innerHTML = "";
    try {
        const { data, error } = await window.mySupabase.from('students').select('id, name, username').order('name');
        if (error || !data) return;
        data.forEach(s => {
            const opt = document.createElement('option');
            opt.value = s.id;
            opt.innerText = s.name || s.username;
            drop.appendChild(opt);
        });
        if (data.length > 0) refreshAdminReportSubjects();
    } catch (e) { /* dropdown stays empty on network issue */ }
}

async function refreshAdminReportSubjects() {
    const studentId = document.getElementById('admin-report-student').value;
    await loadReportSubjectChecklist(studentId, 'admin-report-subjects');
}

function generateAdminReportCard() {
    const studentName = document.getElementById('admin-report-student').selectedOptions[0]?.innerText || 'Student';
    generateReportCard(studentName, 'admin-report-subjects', 'admin-report-remark');
}

// --- Student: view/download report cards sent to their portal ---
window._reportCardsCache = {};

async function loadMyReportCards() {
    const popContainer = document.getElementById('my-popquiz-reports');
    const monthlyContainer = document.getElementById('my-monthly-reports');
    popContainer.innerHTML = "<p style='color:#888;'>Loading...</p>";
    monthlyContainer.innerHTML = "<p style='color:#888;'>Loading...</p>";

    try {
        const { data, error } = await window.mySupabase
            .from('report_cards').select('*')
            .eq('student_id', window.APP.currentUserId)
            .order('created_at', { ascending: false });
        if (error) { popContainer.innerHTML = monthlyContainer.innerHTML = `<p style="color:#d9534f;">${error.message}</p>`; return; }

        const { data: teachers } = await window.mySupabase.from('teachers').select('id, name, username');
        const teacherNameById = {};
        (teachers || []).forEach(t => { teacherNameById[t.id] = t.name || t.username; });

        window._reportCardsCache = {};
        (data || []).forEach(r => { window._reportCardsCache[r.id] = r; });

        const popRows = (data || []).filter(r => r.report_type === 'pop_quiz');
        const monthlyRows = (data || []).filter(r => r.report_type === 'monthly');

        popContainer.innerHTML = popRows.length === 0
            ? "<p style='color:#888;'>No pop quiz report cards yet.</p>"
            : popRows.map(r => reportRowHtml(r, teacherNameById[r.teacher_id] || 'Teacher')).join('');

        monthlyContainer.innerHTML = monthlyRows.length === 0
            ? "<p style='color:#888;'>No monthly report cards yet.</p>"
            : monthlyRows.map(r => reportRowHtml(r, 'Combined - All Subjects')).join('');
    } catch (err) {
        popContainer.innerHTML = monthlyContainer.innerHTML = "<p style='color:#d9534f;'>Unable to connect to database.</p>";
    }
}

function reportRowHtml(r, subtitle) {
    return `
        <div class="qb-card">
            <div class="qb-q-title">${formatPeriodLabel(r.period_start, r.period_end)}</div>
            <p style="font-size:13px;color:#666;margin:4px 0 10px;">${subtitle} — ${r.overall_percentage}% (Grade ${r.overall_grade})</p>
            <div class="action-btn-group">
                <button class="btn-gold" style="width:auto;" onclick="viewStoredReport(${r.id})">View / Print</button>
                <button class="btn-secondary" style="width:auto;" onclick="downloadStoredReport(${r.id})">Download</button>
            </div>
        </div>`;
}

function viewStoredReport(reportId) {
    const r = window._reportCardsCache[reportId];
    if (!r) return;
    const studentName = document.getElementById('student-welcome').innerText.replace('Welcome, ', '').replace('!', '');
    const bannerLabel = r.report_type === 'pop_quiz' ? 'Pop Quiz Report Card' : 'Monthly Report Card';
    const html = buildReportHtml({ studentName, bannerLabel, periodLabel: formatPeriodLabel(r.period_start, r.period_end), rows: r.subjects, remark: r.remark });
    openHtmlInNewTab(html);
}

function downloadStoredReport(reportId) {
    const r = window._reportCardsCache[reportId];
    if (!r) return;
    const studentName = document.getElementById('student-welcome').innerText.replace('Welcome, ', '').replace('!', '');
    const bannerLabel = r.report_type === 'pop_quiz' ? 'Pop Quiz Report Card' : 'Monthly Report Card';
    const html = buildReportHtml({ studentName, bannerLabel, periodLabel: formatPeriodLabel(r.period_start, r.period_end), rows: r.subjects, remark: r.remark });
    downloadHtml(html, `${studentName.replace(/\s+/g, '_')}_${r.report_type}_Report_Card.html`);
}
